units.raw_tex:
For \cref{eq:quadratic}, any suitable solver for regularized
optimization, such as (accelerated) proximal gradient,
(variance-reduced) stochastic gradient methods, and their variants,
can be used, and the following are common for their inner loop
termination:
\begin{gather}
	\hat Q_t - Q_t^* \leq \epsilon_t,
	\label{eq:subprob}\\
\left\| r^t \right\| \leq \epsilon_t,
\quad \text{ or }
	\label{eq:partial}\\
G^\tau_{H_t} \left( p^t;x^t \right)\coloneqq \norm{p^t - \bar
p^t_\tau}\leq \epsilon_t,
	\label{eq:gm}
\end{gather}
for some given $\epsilon_t\geq 0$ and $\tau > 0$, where
\begin{align}
\label{eq:p}
\bar p^t_\tau &\coloneqq \prox_{\tau \Psi}\left(\left(x^t + p^t \right) -
	\tau \left(\nabla f(x^t) + H_t p^t\right)\right) - x^t.
\end{align}
\modify{
The point $\bar p^t_\tau$ in \cref{eq:p} is computed by taking a
proximal gradient step of the subproblem \cref{eq:quadratic} from
$p^t$, and thus $\bar p^t - p^t$ is \modifyy{the proximal gradient}
(with step size $\tau$) of $Q_t$ at $p^t$.
Because the subproblem is strongly convex, the norm of the proximal
gradient is zero at $p^t$ if and only if $p^t$ is the unique solution
to the subproblem.
We will see in the next subsection that the norm of this proximal
gradient squared is also equivalent to the objective distance to the
optimum of the subproblem.}

\begin{algorithm}[h]
\DontPrintSemicolon
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
\caption{A Framework of \ipvm for \cref{eq:f}}
\label{alg:vm}
\Input{$x^0 \in \H$, $\gamma, \beta \in (0,1)$}

\For{$t=0,1,\dotsc$}{
	$\alpha_t \leftarrow 1$,
	pick $\epsilon_t \geq 0$ and $H_t$, and solve \cref{eq:quadratic}
	for $p^t$ satisfying \cref{eq:subprob},
	\cref{eq:partial}, or \cref{eq:gm}


	\lWhile{\cref{eq:armijo} is not satisfied}
	{$\alpha_t \leftarrow \beta \alpha_t$}
	$x^{t+1} \leftarrow x^t + \alpha_t p^t$
}
\end{algorithm}

\subsection{Basic Properties}
Under \cref{assum:Hbound}, \cref{eq:Qdef} is $m$-strongly convex with
respect to $p$, so the following standard results hold for any $\tau
\in (0, 1/M]$ and any $p^t \in \H$ \citep{Nes18a,DruL16a}.
\begin{gather}
\|r^t\|^2 \geq 2 m \left( Q_t(p^t) - Q_t^* \right)
\geq \frac{m}{M} G^\tau_{H_t}\left(
	p^t;x^t \right)^2,
\label{eq:PG}\\
G^\tau_{H_t}\left( p^t;x^t \right)^2 \geq \tau \left( \frac{(2m^{-1} +
	\tau)(1 + M \tau)}{\tau} - \frac{1}{2} \right)^{-1}
	\left(Q_t\left( \bar p^t_\tau\right) - Q_t^* \right).
\label{eq:EB}
\end{gather}

statement.raw_tex:
\begin{theorem}
Consider the setting of \cref{thm:identify1}.
If \cref{alg:vm} is run with \cref{eq:subprob} and
\cref{eq:multiplicative} for some $\eta \in [0,1)$,
	\cref{assum:Hbound} holds,
and the update direction $p^{t}$ satisfies
\begin{equation}
	\label{eq:prox}
	x^t + p^{t} = \prox^{\Lambda_{t}}_{\Psi}\left(y^{t} -
	\Lambda_{t}^{-1} \left( \nabla f\left( x^t \right) + H_t \left( y^{t} -
	x^t \right) + s^{t} \right) \right),
\end{equation}
where $s^{t}$ satisfies $\|s^{t}\| \leq R\left( \norm{y^{t}
- (x^t + p^{t*})} \right)$ for some \modify{$R:[0,\infty) \rightarrow
[0,\infty)$ continuous in its domain} with $R(0) = 0$,
$\Lambda_{t} \in \SS$ with $M_1 \succeq \Lambda_{t}$ for $M_1 >
0$, and $y^{t}$ satisfies
\begin{align}
\label{eq:bdd0}
\norm{\left(y^{t} - x^t\right) - p^{t*}} &\leq \eta_1 \left(Q_t(0) -
Q_t^*\right)^\nu
\end{align}
for some $\nu > 0$ and $\eta_1 \geq 0$,
then there exists $\epsilon, \delta > 0$ such that $\|x^t - x^*\| \leq
\delta, |Q_t^*| \leq \epsilon$, and $\alpha_t = 1$ imply $x^{t+1} \in \M$.
\label{thm:identify2}
\end{theorem}

