\begin{lemma}
Consider \cref{eq:f} with $f\in \mathcal{C}^1$ and $\Psi$
partly
smooth at a point $x^*$ relative to a $\mathcal{C}^2$-manifold
$\M$.
If $\Psi$ is prox-regular at $x^*$,
the nondegenerate condition
\begin{equation}
0 \in \relint \left(\partial F(x^*)\right) = \nabla f(x^*) + \relint
\left(\partial \Psi(x^*)\right)
\label{eq:nod}
\end{equation}
holds, and there is a sequence $\{x^t\}$ converging to $x^*$ with
$F(x^t) \rightarrow F(x^*)$,
then
\[
	\dist\left( 0, \partial F(x^t) \right) \rightarrow 0
	\quad \Leftrightarrow \quad x^t \in \M \text{ for all t large}.
\]
\label{lemma:identify0}
\end{lemma}

\begin{proof}
We first observe that as $f \in \mathcal{C}^1$, $x^t \rightarrow x^*$
implies $f(x^t) \rightarrow f(x^*)$,
whose combination with $F(x^t) \rightarrow F(x^*)$ further implies
$\Psi(x^t) \rightarrow \Psi(x^*)$.
Therefore, the premises of \cite[Theorem~4.10]{LewZ13a} on $\Psi$ are
satisfied.
We then note that
\begin{equation}
	\label{eq:convdist}
	\dist\left(0, \partial F(x^t)\right) \rightarrow 0 \quad
	\Leftrightarrow \quad
	\dist\left(-\nabla f(x^t), \partial \Psi(x^t)\right) \rightarrow 0.
\end{equation}
Again from that $f \in \mathcal{C}^1$, $x^k \rightarrow x^*$ implies
$\nabla f(x^k) \rightarrow \nabla f(x^*)$,
so by \cref{eq:nod}, \cref{eq:convdist} is
further equivalent to
\[
	\dist\left(-\nabla f(x^*), \partial \Psi(x^t)\right) \rightarrow
	0,
\]
which is the necessary and sufficient condition for $x^t \in \M$ for
all $t$ large in \cite[Theorem~4.10]{LewZ13a} because \cref{eq:nod}
indicates that $- \nabla f(x^*) \in \relint(\partial \Psi(x^*))$.
We then apply that theorem to obtain the desired result.
Here we note that for the requirements
\qed
\end{proof}

\begin{lemma}
	Consider \cref{eq:f} with \modify{$f \in \mathcal{C}^1$} and $\Psi \in
\Gamma_0$.
If $\Psi$ is partly smooth relative to a manifold $\M$ at a point
\modify{$x^*$ satisfying \cref{eq:nod}}, and there is a sequence $\{x^t\}$
converging to $x^*$, then we have
\[
	\dist\left( 0, \partial F(x^t) \right) \rightarrow 0
	\quad \Rightarrow \quad x^t \in \M \text{ for all t large}.
\]
\label{lemma:identify}
\end{lemma}

\begin{proof}
As $\Psi \in \Gamma_0$, it is subdifferentially continuous at
$x^* \in \dom(\Psi)$ by \cite[Example 13.30]{RocW09a}.
Thus, $\dist(0, \partial F(x^t)) \rightarrow 0 \in \partial F(x^*)$
and $x^t \rightarrow x^*$ imply that $F(x^t) \rightarrow F(x^*)$.
The desired result is then obtained by applying
\modify{\cref{lemma:identify0}}.
\qed
\end{proof}

\begin{theorem}
Consider a point $x^*$ satisfying \cref{eq:nod} with $\Psi \in \Gamma_0$
partly smooth at $x^*$ relative to some manifold $\M$.
Assume $f$ is locally $L$-smooth
for $L > 0$ around $x^*$.
If \cref{alg:vm} is run with the condition \cref{eq:partial} and
\cref{assum:Hbound} holds,
then
there exist $\epsilon, \delta > 0$ such that
$\|\modify{x^t} - x^* \| \leq \delta, \epsilon_t \leq \epsilon$, and $\alpha_t = 1$
imply $x^{t+1} \in \M$.
\label{thm:identify1}
\end{theorem}

\begin{proof}
Since each iteration of \cref{alg:vm} is independent of the previous
ones, we abuse the notation to let $x^t$ be the input of
\cref{alg:vm} at the $t$th iteration and $p^t$ the corresponding
inexact solution to \cref{eq:quadratic}, but $x^{t+1}$ is
irrelevant to $p^t$ or $\alpha_t$.
Assume for contradiction the statement is false.
Then there exist a sequence $\{x^t\}\subset \H$ converging to $x^*$, a
nonnegative sequence $\{\epsilon_t\}$ converging to $0$, a sequence
$\{H_t\} \subset \SS$ satisfying \cref{assum:Hbound}, and a sequence
$\{p^t\}\subset \H$ such that $Q_{H_t}(p^t;x^t)$ in \cref{eq:Qdef}
satisfies
\cref{eq:partial} for all $t$, yet $x^t + p^t \notin \M$ for all $t$.
From \cref{eq:subnorm},
\begin{equation}
	r^t - \nabla f\left( x^t \right) - H_t p^t
	\in \partial \Psi\left( x^{t} + p^t \right), \quad \forall t \ge 0.
\label{eq:r}
\end{equation}
Therefore, we get from \cref{eq:r} that
\begin{align}
	\nonumber
	\dist\left(0, \partial F\left(x^t + p^t \right) \right) &=
	\dist\left(-\nabla f\left( x^t + p^t \right), \partial \Psi\left(
	x^t + p^t \right)\right)\\
	\nonumber
	&\leq \norm{-\nabla f\left( x^t + p^t\right) - \left(r^{t} - \nabla
	f\left( x^{t} \right) - H_{t} p^t \right)}\\
	\nonumber
	&\leq \norm{\nabla f\left( x^t + p^t\right) - \nabla f\left( x^{t}
	\right)} + \norm{r^{t}} +
	\norm{H_{t}} \norm{p^t}\\
	&\leq \left(L + M \right) \norm{p^t} + \norm{r^{t}}.
	\label{eq:dist}
\end{align}
From \cref{assum:Hbound} and the convexity of $\Psi$,
$Q_{H_t}(\cdot;x^t)$ is $m$-strongly convex, which implies
\begin{equation}
	Q_{H_t}\left(p;x^t \right) - Q_{H_t}\left( p^{t*};x^t \right) \geq
\frac{m}{2} \norm{p - p^{t*}}^2, \quad  \forall p \in \H.
\label{eq:qg}
\end{equation}
Combining \cref{eq:qg} and \cref{eq:PG} shows that
\begin{equation}
	\label{eq:pbound}
	m^{-1} \|r^t\| + \|p^{t*}\| \geq \|p^t\|.
\end{equation}
Since $\{x^t\}$ converges to $x^*$, by the argument in
\cite[Lemma~3.2]{Wri12a}, we get
\begin{equation}
p^{t*} = O(\|x^t - x^*\|)
\label{eq:pt}
\end{equation}
whenever $x^t$ is close enough to $x^*$.
Thus \cref{eq:pbound}, \cref{eq:pt}, \cref{eq:partial}, and that
$\epsilon_t \downarrow 0$ imply
\begin{equation}
\lim_{t \rightarrow \infty} \|p^t\| = 0,
\label{eq:pt2}
\end{equation}
Substituting \cref{eq:partial} and \cref{eq:pt2} into \cref{eq:dist}
gives $\dist(0, \partial F(x^t)) \rightarrow 0$, and by \cref{eq:pt2}
we also get $ x^t + p^t \rightarrow x^* + 0 = x^*$.  Therefore
\cref{lemma:identify} implies that
$x^{t} + p^{t} \in \M$ for all $t$ large enough, proving the
desired contradiction.
\qed
\end{proof}

\begin{proof}
Suppose the statement is not true for contradiction.
Then there exist a continuous \modify{function $R: [0, \infty)
\rightarrow [0, \infty)$ with}
$R(0) = 0$, $\eta_1 \geq 0$, $M_1 > 0$, a sequence $\{x^t\} \subset
\H$ converging to $x^*$,
a sequence $\{H_t\} \subset \SS$ satisfying \cref{assum:Hbound} and
\begin{equation}
\lim_{t \rightarrow \infty}\, \min_{p}\quad Q_{H_t}\left( p;x^t
\right) = 0,
\label{eq:Qconv}
\end{equation}
three sequences $\{p^t\}, \{y^t\}, \{s^t\} \subset \H$
and a sequence $\{\Lambda_t\}\subset \SS$ with $M_1 \succeq \Lambda_t$
such that \cref{eq:subprob} with \cref{eq:multiplicative} and
\cref{eq:prox}-\cref{eq:bdd0} hold, yet $x^t + p^t \notin \M$
for all $t$.
We abuse the notation to let $p^{t*}$ and $Q^*_t$
respectively denote the optimal solution and objective value for
$\min_p Q_{H_t}(p;x^t)$, but $x^{t+1}$ is irrelevant to $p^t$ or
$\alpha_t$.

The optimality condition of \cref{eq:proximal} applied to
\cref{eq:prox} indicates that
\begin{equation}
	-\Lambda_{t}\left(x^{t} - y^{t}\right) - \left( \nabla
	f\left( x^t \right) + H_t \left( y^{t} - x^t \right) + s^{t}
	\right) \in \partial \Psi\left( x^{t} + p^t \right).
	\label{eq:opt}
\end{equation}
Thus, we have
\begin{align}
\nonumber
&~\dist\left( 0, \partial F\left( x^t + p^t \right) \right)\\
\nonumber
\leq &~\left\|\nabla f\left( x^t + p^t
	\right) -\Lambda_{t}\left(x^t + p^t -
	y^{t}\right) - \nabla f\left( x^{t} \right) \right.
	\left. -
	H_{t} \left( y^{t} - x^{t} \right) -
	s^{t} \right\|\\
\nonumber
\leq &~\norm{\nabla f\left( x^t + p^t \right)- \nabla
	f\left( x^{t} \right)} + M_1 \left( \norm{x^t - y^{t}} +
	\norm{p^t}\right)
	+ M
	\norm{y^{t} - x^{t}} + \norm{s^{t}}\\
\leq &~(L + M_1) \norm{p^t} +
	(M + M_1) \norm{y^{t} - x^{t}} +
	\norm{s^{t}}.
\label{eq:tobdd}
\end{align}
For the first two terms in \cref{eq:tobdd}, the
triangle inequality and \cref{eq:qg} imply
\begin{gather}
	\begin{aligned}
\norm{p^{t}} 
\leq \norm{p^{t} - p^{t*}} + \norm{p^{t*}}
\leq
&~\sqrt{2m^{-1}}\sqrt{ Q_{t}\left( p^{t} \right) -
Q^*_{t} } + \sqrt{2m^{-1}}\sqrt{ 0 - Q^*_{t}}\\
\stackrel{\cref{eq:multiplicative}}{\leq}&~ \left( \sqrt{\eta} + 1
\right)\sqrt{2m^{-1}}\sqrt{ - Q^*_{t}}, \text{ and }
\end{aligned}
\label{eq:bdd1}\\
\norm{y^{t}- x^{t}}
\leq \norm{\left(y^{t}- x^{t}\right) - p^{t*}} +
\norm{p^{t*}}
\stackrel{\cref{eq:bdd0}}{\leq}
\eta_1 \left( - Q^*_{t}\right)^\nu + \sqrt{2m^{-1}}\sqrt{ - Q^*_{t}}.
\label{eq:bdd3}
\end{gather}
For the last term in \cref{eq:tobdd}, we have from \modify{our definition of
$s^t$ that
\begin{align}
\norm{s^{t}} &\leq
R \left(\norm{y^{t} - \left(x^{t} + p^{t*}\right)}\right).
\label{eq:bdd4}
\end{align}
}
By substituting \cref{eq:bdd1}-\cref{eq:bdd4} back into
\cref{eq:tobdd}, clearly there are $C_1, C_2 > 0$ such that
\begin{equation}
\dist\left( 0, \partial F\left( x^t + p^t \right) \right)
\leq
C_1 \sqrt{ - Q^*_t} + C_2 \left( -Q^*_t \right)^\nu \modify{+
	R \left(\norm{y^{t} - \left(x^{t} + p^{t*}\right)}\right).}
\label{eq:tobdd2}
\end{equation}
Note that $Q_{H_t}(0;x^t) \equiv 0$, so $-Q^*_t \geq 0$ from its
optimality and the right-hand side of  \cref{eq:tobdd2} is
well-defined.
\modify{Next, we see from \cref{eq:Qconv}, \cref{eq:bdd0}, and the
continuity of $R$ that
\begin{equation}
\lim_{t \rightarrow \infty} \norm{\left(y^{t} - x^t\right) - p^{t*}} =
0, \quad \Rightarrow \quad
\lim_{t \rightarrow \infty} R\left( \norm{\left(y^{t} - x^t\right) -
p^{t*}}\right) =
0.
\label{eq:sconv}
\end{equation}
Applying \cref{eq:Qconv} and \cref{eq:sconv}} to \cref{eq:tobdd2} and
letting $t$ approach infinity then yield
\begin{equation}
\lim_{t \rightarrow \infty} \dist\left( 0, \partial F\left(
x^t + p^t \right) \right) = 0.
\label{eq:partialconv}
\end{equation}

Next, from \cref{eq:bdd1} and \cref{eq:Qconv}, it is also clear that
$\norm{p^t} \rightarrow 0$,
so from the convergence of $x^t$ to $x^*$ we have
\begin{equation}
x^t + p^t \rightarrow x^* + 0 = x^*.
\label{eq:convxp}
\end{equation}
Now \cref{eq:convxp} and \cref{eq:partialconv} allow us to apply
\cref{lemma:identify}
so $x^t + p^t \in \M$ for all $t$ large enough,
leading to the desired contradiction.
\qed
\end{proof}

