\begin{definition}[Partly smooth]
	\label{def:ps}
	A function $\Psi$ is partly
	smooth at a point $x^*$ relative to a set $\M$ containing $x^*$ if
	$\partial \Psi(x^*) \neq \emptyset$ and:
	\begin{enumerate}
			\item Around $x^*$, $\M$ is a $\mathcal{C}^2$-manifold and
				$\Psi|_{\M}$ is $\mathcal{C}^2$.
		\item The affine span of $\partial \Psi(x)$ is a translate
			of the normal space to $\M$ at $x^*$.
		\item $\partial \Psi$ is continuous at $x^*$ relative to $\M$.
		\item \modify{$\Psi$ is regular at all points $x \in \M$ with
			$\partial \Psi(x) \neq  \emptyset$
		around $x^*$.}
	\end{enumerate}
\end{definition}

